# Created by OpenAI
"""Block-scaled FP8 GEMM for N=7168, K=2048 on gfx950, scheduled for M=64.

out = (a * a_scale) @ (b * b_scale).T in bfloat16: E4M3FN operands, an FP32 scale per
1 x 128 block of a and per 128 x 128 block of b, row-major operands.
"""

import torch
from triton.experimental import gluon
from triton.experimental.gluon import language as gl


@gluon.jit
def _swizzled_k(rows, kk):
    return ((kk[None, :] // 16) ^ (rows[:, None] % 16)) * 16 + kk[None, :] % 16


@gluon.jit
def _allocate_panels(P, ROWS: gl.constexpr, BK: gl.constexpr,
                     LAYOUT: gl.constexpr, SLOTS: gl.constexpr):
    buffers = ()
    for slot in gl.static_range(SLOTS):
        buffers += (gl.allocate_shared_memory(P.dtype.element_ty, (ROWS, BK), LAYOUT),)
    return buffers


@gluon.jit
def _load_scale_range(
    XS, WS, rows, col_start,
    SXSM: gl.constexpr, SXSK: gl.constexpr,
    SWSN: gl.constexpr, SWSK: gl.constexpr,
    BEGIN: gl.constexpr, END: gl.constexpr, sx=(), sw=(),
    LOAD_X: gl.constexpr = True, LOAD_W: gl.constexpr = True,
):
    for group in gl.static_range(BEGIN, END):
        if LOAD_X:
            sx += (gl.load(XS + rows * SXSM + group * SXSK),)
        if LOAD_W:
            sw += (gl.load(WS + (col_start // 128) * SWSN + group * SWSK),)
    return sx, sw


@gluon.jit
def _form_factor_window(sx, sw, BEGIN: gl.constexpr, END: gl.constexpr, factors=()):
    for group in gl.static_range(BEGIN, END):
        factors += (sx[group] * sw[group],)
    return factors


@gluon.jit
def _group_dot(a, b, zero, GROUP: gl.constexpr):
    M: gl.constexpr = zero.type.shape[0]
    BN: gl.constexpr = zero.type.shape[1]
    aa = gl.amd.slice(a, (M, 128), (0, GROUP * 128))
    bb = gl.amd.slice(b, (128, BN), (GROUP * 128, 0))
    return gl.amd.cdna4.mfma_scaled(aa, None, "e4m3", bb, None, "e4m3", zero)


@gluon.jit
def _accumulate_panel(acc, a, b, zero, sx, sw, STAGE: gl.constexpr,
                      BUNDLE_DOTS: gl.constexpr, FACTORED: gl.constexpr = False,
                      REUSE: gl.constexpr = False):
    pair = ()
    if REUSE:


        pair = (sx[STAGE * 2] * sw[STAGE * 2], sx[STAGE * 2 + 1] * sw[STAGE * 2 + 1])
    dots = ()
    if BUNDLE_DOTS:
        for group in gl.static_range(2):
            dots += (_group_dot(a, b, zero, group),)
    for group in gl.static_range(2):
        if BUNDLE_DOTS:
            dot = dots[group]
        else:
            dot = _group_dot(a, b, zero, group)
        if REUSE:
            scaled = dot * pair[group][:, None]
        elif FACTORED:
            scaled = dot * sx[STAGE * 2 + group][:, None]
        else:
            scaled = dot * sx[STAGE * 2 + group][:, None] * sw[STAGE * 2 + group]
        if STAGE == 0 and group == 0:
            acc = scaled
        else:
            acc = acc + scaled
    return acc


@gluon.jit
def _store_output(acc, Y, col_start, N: gl.constexpr):
    M: gl.constexpr = acc.type.shape[0]
    BN: gl.constexpr = acc.type.shape[1]
    if M == 32:
        STORE: gl.constexpr = gl.BlockedLayout([1, 4], [16, 4], [2, 2], [1, 0])
    else:
        STORE: gl.constexpr = gl.BlockedLayout([1, 8], [16, 4], [4, 1], [0, 1])
    out = gl.convert_layout(acc.to(gl.bfloat16), STORE)
    rows = gl.arange(0, M, gl.SliceLayout(1, STORE))
    cols = gl.arange(0, BN, gl.SliceLayout(0, STORE))
    gl.amd.cdna4.buffer_store(
        out, Y + col_start, rows[:, None] * N + cols[None, :],
        cache=".wb" if M == 32 else ".wt",
    )


@gluon.jit
def _copy_panel(shared, base, offsets):
    linear: gl.constexpr = gl.SwizzledSharedLayout(16, 1, 1, [1, 0])
    gl.amd.cdna4.async_copy.buffer_load_to_shared(
        shared._reinterpret(layout=linear), base, offsets,
    )


@gluon.jit
def _copy_pair(
    a_shared, b_shared, X, W, ax, bw, WEIGHT_FIRST: gl.constexpr,
    SPLIT_COMMIT: gl.constexpr = False, X_OFFSET: gl.constexpr = 0,
):
    if WEIGHT_FIRST:
        _copy_panel(b_shared, W, bw)
        if SPLIT_COMMIT:
            gl.amd.cdna4.async_copy.commit_group()
        _copy_panel(a_shared, X + X_OFFSET, ax)
    else:
        _copy_panel(a_shared, X, ax)
        if SPLIT_COMMIT:
            gl.amd.cdna4.async_copy.commit_group()
        _copy_panel(b_shared, W, bw)
    gl.amd.cdna4.async_copy.commit_group()


@gluon.jit
def _stage_activation_scales(XS, M: gl.constexpr, SXSM: gl.constexpr, SXSK: gl.constexpr):
    COPY: gl.constexpr = gl.BlockedLayout([1, 4], [16, 4], [4, 1], [1, 0])
    if M == 32:
        SHARED: gl.constexpr = gl.PaddedSharedLayout.with_identity_for(
            [[M, 4]], [M, 16], [0, 1],
        )
    else:
        SHARED: gl.constexpr = gl.SwizzledSharedLayout(1, 1, 1, [0, 1])
    rows = gl.arange(0, M, gl.SliceLayout(1, COPY))
    groups = gl.arange(0, 16, gl.SliceLayout(0, COPY))
    values = gl.load(XS + rows[:, None] * SXSM + groups[None, :] * SXSK)
    return gl.allocate_shared_memory(gl.float32, (M, 16), SHARED, values)


@gluon.jit
def _pipeline_output(
    X, XS, W, WS, Y,
    M: gl.constexpr, N: gl.constexpr,
    SXM: gl.constexpr, SXK: gl.constexpr,
    SXSM: gl.constexpr, SXSK: gl.constexpr,
    SWN: gl.constexpr, SWK: gl.constexpr,
    SWSN: gl.constexpr, SWSK: gl.constexpr,
):

    BN: gl.constexpr = 32
    BK: gl.constexpr = 256
    STAGES: gl.constexpr = 8
    SLOTS: gl.constexpr = 3 if M == 64 else 4
    PREFETCH: gl.constexpr = 2 if M == 64 else 3
    if M == 32:
        WAITS: gl.constexpr = (2, 3, 4, 4, 4, 4, 2, 0)
    else:
        WAITS: gl.constexpr = (1, 2, 2, 2, 2, 2, 2, 0)
    tile = gl.program_id(0).to(gl.uint32)
    if M == 64:


        quotient = (tile * 293) >> 13
        tile = tile * 8 - quotient * 223
    col_start = tile * BN
    copy: gl.constexpr = gl.BlockedLayout([1, 16], [4, 16], [4, 1], [1, 0])
    shared_layout: gl.constexpr = gl.SwizzledSharedLayout(16, 1, 16, [1, 0])
    mma: gl.constexpr = gl.amd.AMDMFMALayout(
        version=4, instr_shape=[16, 16, 128], transposed=True,
        warps_per_cta=[M // 16, 64 // M],
    )
    dot_a: gl.constexpr = gl.DotOperandLayout(0, mma, 32)
    dot_b: gl.constexpr = gl.DotOperandLayout(1, mma, 32)
    ar = gl.arange(0, M, gl.SliceLayout(1, copy))
    bc = gl.arange(0, BN, gl.SliceLayout(1, copy))
    kk = gl.arange(0, BK, gl.SliceLayout(0, copy))
    ak = _swizzled_k(ar, kk)
    bk = _swizzled_k(bc, kk)
    ax = ar[:, None] * SXM + ak * SXK
    bw = bc[:, None] * SWN + bk * SWK
    if M == 32:

        a_arena = gl.allocate_shared_memory(X.dtype.element_ty, (SLOTS, M, BK), shared_layout)
        b_arena = gl.allocate_shared_memory(W.dtype.element_ty, (SLOTS, BN, BK), shared_layout)
        a_buffers, b_buffers = (), ()
        for slot in gl.static_range(SLOTS):
            a_buffers += (a_arena.index(slot),)
            b_buffers += (b_arena.index(slot),)
    else:
        a_buffers = _allocate_panels(X, M, BK, shared_layout, SLOTS)
        b_buffers = _allocate_panels(W, BN, BK, shared_layout, SLOTS)
    zero = gl.zeros((M, BN), gl.float32, mma)
    rows = gl.arange(0, M, gl.SliceLayout(1, mma))
    TABLE_SCALES: gl.constexpr = SXSK != 1
    if TABLE_SCALES:
        scale_table = _stage_activation_scales(XS, M, SXSM, SXSK)
    FACTORED: gl.constexpr = M == 32
    EARLY_SCALES: gl.constexpr = 0 if TABLE_SCALES else (8 if M == 64 else 16)
    all_sx, all_sw = (), ()
    if M == 64 or TABLE_SCALES:
        all_sx, all_sw = _load_scale_range(
            XS, WS, rows, col_start, SXSM, SXSK, SWSN, SWSK, 0, 16, LOAD_X=False,
        )
    all_sx, all_sw = _load_scale_range(
        XS, WS, rows, col_start, SXSM, SXSK, SWSN, SWSK,
        0, EARLY_SCALES, all_sx, all_sw, LOAD_W=M != 64 and not TABLE_SCALES,
    )
    factors = ()
    if FACTORED and not TABLE_SCALES:


        factors = _form_factor_window(all_sx, all_sw, 0, 4)
    for panel in gl.static_range(PREFETCH):
        _copy_pair(
            a_buffers[panel], b_buffers[panel],
            X if M == 64 else X + panel * BK * SXK,
            W + col_start * SWN + panel * BK * SWK,
            ax + panel * BK * SXK if M == 64 else ax, bw, M == 64,
        )
    acc = zero
    for stage in gl.static_range(STAGES):
        gl.amd.cdna4.async_copy.wait_group(WAITS[stage])
        if M == 32:


            gl.barrier()
        if TABLE_SCALES:
            for group in gl.static_range(2):
                scale = scale_table.slice(stage * 2 + group, 1, dim=1).load(mma)
                sx = gl.sum(scale, 1)
                all_sx += (sx,)
                if FACTORED:
                    factors += (sx * all_sw[stage * 2 + group],)
        if M == 32:
            b = gl.amd.cdna4.async_copy.load_shared_relaxed(
                b_buffers[stage % SLOTS].permute((1, 0)), dot_b,
            )
            a = gl.amd.cdna4.async_copy.load_shared_relaxed(a_buffers[stage % SLOTS], dot_a)
        else:
            a = a_buffers[stage % SLOTS].load(dot_a)
            b = b_buffers[stage % SLOTS].permute((1, 0)).load(dot_b)
        if stage < STAGES - PREFETCH:
            _copy_pair(
                a_buffers[(stage + PREFETCH) % SLOTS],
                b_buffers[(stage + PREFETCH) % SLOTS], X,
                W + col_start * SWN + (stage + PREFETCH) * BK * SWK,
                ax + (stage + PREFETCH) * BK * SXK if M == 64 else ax,
                bw, M == 32, True,
                X_OFFSET=(stage + PREFETCH) * BK * SXK if M == 32 else 0,
            )
        if M == 64 and stage == 0 and not TABLE_SCALES:
            all_sx, all_sw = _load_scale_range(
                XS, WS, rows, col_start, SXSM, SXSK, SWSN, SWSK,
                EARLY_SCALES, 16, all_sx, all_sw, LOAD_W=False,
            )
        if FACTORED and not TABLE_SCALES:

            if (stage * 2 + 2) % 4 == 0 and stage * 2 + 2 < 16:
                factors = _form_factor_window(
                    all_sx, all_sw, stage * 2 + 2, stage * 2 + 6, factors,
                )
        acc = _accumulate_panel(
            acc, a, b, zero, factors if FACTORED else all_sx, all_sw,
            stage, M == 64, FACTORED, REUSE=M == 64 and stage >= 3,
        )
    if TABLE_SCALES:
        scale_table._keep_alive()
    if M == 32:
        for slot in gl.static_range(SLOTS):
            a_buffers[slot]._keep_alive()
        for slot in gl.static_range(SLOTS):
            b_buffers[slot]._keep_alive()
    _store_output(acc, Y, col_start, N)


def fp8_a8w8_block_scaled_gemm_fn(
    x: torch.Tensor,
    x_scales: torch.Tensor,
    weight: torch.Tensor,
    weight_scales: torch.Tensor,
    *,
    out: torch.Tensor,
    group_n: int = 128,
    group_k: int = 128,
    block_m: int = 32,
    precision_config=None,
) -> None:
    m, k = x.shape
    n = weight.shape[0]
    assert m in (32, 64) and n == 7168 and k == 2048
    assert group_n == 128 and group_k == 128
    _pipeline_output[(n // 32,)](
        x, x_scales, weight, weight_scales, out, m, n,
        *x.stride(), *x_scales.stride(), *weight.stride(), *weight_scales.stride(),
        num_warps=4, num_stages=1, waves_per_eu=1 if m == 32 else 2,
    )


def run(a, b, a_scale, b_scale, out):
    scale_major_mode = 'K'
    use_shuffled_weight = False
    out_dtype = out.dtype
    fp8_a8w8_block_scaled_gemm_fn(a, a_scale, b, b_scale, out=out)
